def perfect_cube_root(n):
    guess = 0
    while guess ** 3 < n:
        guess += 1
    if guess ** 3 == n:
        return guess
    return None

def to_binary(n):
    if n == 0:
        return '0'
    bits = ''
    while n > 0:
        bits = str(n % 2) + bits
        n = n // 2
    return bits

def longest_vowel_run(s):
    best = 0
    current = 0
    for ch in s.lower():
        if ch in 'aeiou':
            current += 1
            if current > best:
                best = current
        else:
            current = 0
    return best
